The `repeated-defect-audit.v1.json` artifact is generated with a hardcoded empty `rows` array, even when `repeated_defect_count` is non-zero. This is inconsistent with other audit artifacts like `false-accept-override-audit.v1.json` which do populate their `rows` array.

To improve the utility of the generated artifact for debugging and analysis, the `rows` array should be populated with details of the defects that were counted. This makes the artifact self-contained.

```python
    repeated_defect_rows = [
        {
            "question_id": row["question_id"],
            "repair_reason": row["repair_reason"],
            "family": row["layout_family"],
        }
        for row in ordered
        if row["repair_reason"]
        in {
            "direct-structural-omission",
            "direct-mark-owner-omission",
            "extra-subpart",
            "extra-or-invalid-subpart",
        }
    ]
    repeated_defects = len(repeated_defect_rows)
    gates = {"final_exact_match_at_least_97_percent": final / total >= .97, "zero_false_accepts": false_accepts == 0, "zero_false_overrides": false_overrides == 0, "zero_question_year_truth_aware_behavior": True, "zero_repeated_1645_structural_defects": repeated_defects == 0, "zero_context_truncation_misclassification": context_failures == 0, "deterministic_reconstruction_and_immutable_history": True, "zero_provider_transport_terminal_failures": provider_failures == 0, "no_unresolved_truth_schema_ambiguity": True}
    summary = {"schema_version": "9709_final_holdout_validation_summary_v1", "issue": ISSUE, "classification": "independent_seven_complete_paper_holdout", "run_id": run_id, "paper_count": 7, "question_count": total, "first_pass": {"correct": first, "total": total, "rate": first / total}, "final_exact_match": {"correct": final, "total": total, "rate": final / total}, "layout_family_distribution": dict(sorted(family_counts.items())), "terminal_counts": dict(sorted(status_counts.items())), "false_accept_count": false_accepts, "false_override_count": false_overrides, "repeated_defect_count": repeated_defects, "gates": gates, "batch_readiness_verdict": "pass_supports_separately_authorized_upstream_candidate_production_issue" if all(gates.values()) else "hold_smallest_next_action_required", "strong_result_at_least_99_percent": final / total >= .99 and all(gates.values()), "historical_truth_surfaces": {"issue_1641_independent": "326/340", "issue_1645_repaired_regressions": ["335/340", "249/249", "584/589"], "combined_or_averaged": False}, "manifest_sha256": manifest_sha, "truth_sha256": truth_sha, "checkpoint_sha256": sha256_file(checkpoint), "self_sha256_omitted": True}
    candidate_results = {"schema_version": "9709_final_holdout_candidate_results_v1", "issue": ISSUE, "rows": [{key: value for key, value in row.items() if key not in {"full_pass", "mark_pass"}} for row in ordered]}
    residuals = {"schema_version": "9709_final_holdout_residual_ledger_v1", "issue": ISSUE, "rows": [{"question_id": row["question_id"], "paper_id": row["paper_id"], "terminal_status": row["terminal_status"], "family": row["layout_family"], "failed_fields": [key for key, passed in row["checks"].items() if not passed], "bounded_page_level_cause": "ordinary_candidate_visual_or_semantic_disagreement" if row["terminal_status"] == "candidate_complete_with_residual" else row["terminal_status"]} for row in ordered if not row["all_field_checks_pass"]]}
    raw_rows = [{"question_id": row["question_id"], "pass": name, **attempt} for row in ordered for name in ("full_pass", "mark_pass") for attempt in row[name]["attempts"]]
    raw_inventory = {"schema_version": "9709_final_holdout_raw_response_inventory_v1", "issue": ISSUE, "provider_attempt_count": len(raw_rows), "rows": raw_rows}
    budgets = {"schema_version": "9709_final_holdout_context_budget_ledger_v1", "issue": ISSUE, "contract": read_json(CONTEXT_CONTRACT)["budget_policy"], "all_calls_pre_budgeted": all(row["budget"]["status"] == "within_budget" for row in raw_rows), "rows": [{key: row[key] for key in ("question_id", "pass", "attempt_number", "request_identity", "budget", "classification", "finish_reason", "usage", "response_model")} for row in raw_rows]}
    activations = {"schema_version": "9709_final_holdout_repair_family_activation_ledger_v1", "issue": ISSUE, "activation_counts": dict(sorted(Counter(item for row in ordered for item in row["repair_activations"]).items())), "family_counts": dict(sorted(family_counts.items())), "rows": [{"question_id": row["question_id"], "family": row["layout_family"], "status": row["repair_status"], "activations": row["repair_activations"]} for row in ordered if row["repair_activations"]]}
    safety = {"schema_version": "9709_final_holdout_false_accept_override_audit_v1", "issue": ISSUE, "false_accept_count": false_accepts, "false_override_count": false_overrides, "rows": [{"question_id": row["question_id"], "false_accept": row["false_accept"], "false_override": row["false_override"]} for row in ordered if row["false_accept"] or row["false_override"]]}
    defects = {"schema_version": "9709_final_holdout_repeated_defect_audit_v1", "issue": ISSUE, "repeated_defect_count": repeated_defects, "claimed_fixed_classes": ["explicit-unmarked-instruction-owners", "hierarchical-owner-paths", "canonical-whole-question-aliases", "page-aware-roman-continuation-reset", "incomplete-extra-subpart-rejection", "specialized-mark-owner-equivalence"], "rows": repeated_defect_rows}
```
